import type{GeoEntity}from'./geo.js';
export const GEO_SCENE_MAPPING_VERSION='geo-scene-affinity/1';
export const GEO_SCENE_RULES:Readonly<Record<string,{scene:string;weight:number;evidence:string}>>={mountain:{scene:'scene:mountain',weight:.85,evidence:'Source-typed mountain/volcano; no climate/season inference'},lake:{scene:'scene:lake',weight:1,evidence:'Source-typed lake'},coast:{scene:'scene:coast',weight:.9,evidence:'Source-typed coast/beach'},park:{scene:'scene:landscape',weight:.2,evidence:'Verified national-park source type supports weak landscape only; no mountain claim'}};
export function geoSceneEvidence(entities:readonly GeoEntity[]){return entities.flatMap(e=>{const rule=GEO_SCENE_RULES[e.type];return rule?[{...rule,entityId:e.id,placeType:e.type,source:e.source,sourceId:e.sourceId,mappingVersion:GEO_SCENE_MAPPING_VERSION,claim:'soft affinity only; does not mutate the 42-term vocabulary'}]:[];});}
